	print("Root script class_name attached: ", root.get_script() != null)
	if root.has_method("apply_impulse_to"):
		print("apply_impulse_to: OK")
	if root.has_method("freeze_all"):
		print("freeze_all: OK")
	if root.has_method("get_part"):
		print("get_part: OK")
	if root.has_method("get_average_position"):
		print("get_average_position: OK")
	for part_name in ["Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg"]:
		var n = root.get_node_or_null(NodePath(part_name))
		if n == null:
			print("MISSING part: ", part_name)
		elif not (n is RigidBody2D):
			print("WRONG type for: ", part_name, " -> ", n.get_class())
		else:
			print("Part OK: ", part_name, " mass=", n.mass, " has_collision=", n.get_node_or_null("CollisionShape2D") != null, " has_visual=", (n.get_node_or_null("Visual") != null))
	var pin_joints: Array = []
	for child in root.get_children():
		if child is PinJoint2D:
			pin_joints.append(child)
	print("PinJoint2D count: ", pin_joints.size())
	for j in pin_joints:
		var na: NodePath = j.node_a
		var nb: NodePath = j.node_b
		var a: Node = j.get_node_or_null(na)
		var b: Node = j.get_node_or_null(nb)
		print("Joint ", j.name, " a=", na, " b=", nb, " a_resolves=", a != null and a is RigidBody2D, " b_resolves=", b != null and b is RigidBody2D)
	print("Average position: ", root.get_average_position())
	# Also check signal exists
	var sig_list: Array = root.get_signal_list()
	var found_signal := false
	for s in sig_list:
		if s.name == "ragdoll_collapsed":
			found_signal = true
			break
	print("ragdoll_collapsed signal present: ", found_signal)
	print("=== Done ===")
	quit(0)

extends SceneTree

func _initialize() -> void:
	var scene: PackedScene = load("res://scenes/Ragdoll.tscn")
	if scene == null:
		push_error("Failed to load scene")
		quit(1)
		return
	var root: Node = scene.instantiate()
	if root == null:
		push_error("Failed to instantiate scene")
		quit(1)
		return
	get_root().add_child(root)

	var emitted: Array = []
	root.ragdoll_collapsed.connect(func(p: Vector2):
		emitted.append(p)
	)

	# Simulate ~4 seconds of physics
	var elapsed := 0.0
	var steps := 0
	while elapsed < 4.0:
		await physics_frame
		elapsed += 1.0 / 60.0
		steps += 1
		if steps == 20:
			root.apply_impulse_to(&"Torso", Vector2(500, 0))
		if steps == 40:
			root.apply_impulse_to(&"Head", Vector2(-300, 100))
		if steps == 60:
			root.freeze_all(true)
		if steps == 80:
			root.freeze_all(false)
			root.apply_impulse_to(&"LeftArm", Vector2(800, -200))

	print("Total physics steps: ", steps)
	print("Collapse signal emission count: ", emitted.size())
	if emitted.size() > 0:
		print("Collapse position: ", emitted[0])
	else:
		print("WARNING: collapse signal never emitted")

	# Check get_part returns
	var head_part: RigidBody2D = root.get_part(&"Head")
	var bogus_part: RigidBody2D = root.get_part(&"NoSuchPart")
	print("get_part(&\"Head\") is RigidBody2D: ", head_part != null)
	print("get_part(&\"NoSuchPart\") returns null: ", bogus_part == null)

	# Check get_average_position is in reasonable range
	var avg: Vector2 = root.get_average_position()
	print("get_average_position(): ", avg)

	# Confirm freeze_all works
	root.freeze_all(true)
	var all_frozen := true
	for pn in ["Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg"]:
		var p: RigidBody2D = root.get_part(pn)
		if not p.freeze:
			all_frozen = false
	print("All parts frozen after freeze_all(true): ", all_frozen)
	root.freeze_all(false)
	var all_unfrozen := true
	for pn in ["Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg"]:
		var p: RigidBody2D = root.get_part(pn)
		if p.freeze:
			all_unfrozen = false
	print("All parts unfrozen after freeze_all(false): ", all_unfrozen)

	print("=== physics validation done ===")
	quit(0)

